<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $ticket->subject }} · Support inbox</title><style>:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc;--soft:#f8fafc}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px/1.6 Inter,system-ui,sans-serif}a{color:inherit}.shell{max-width:1180px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;gap:20px;margin-bottom:28px}.top a{text-decoration:none;color:var(--muted)}.layout{display:grid;grid-template-columns:1fr 300px;gap:20px}.panel{padding:24px;border:1px solid var(--line);border-radius:18px;background:#fff}.title{margin:0 0 7px;font-size:32px;letter-spacing:-.05em}.muted{color:var(--muted)}.message{padding:18px 0;border-top:1px solid var(--line)}.message:first-child{border-top:0;padding-top:0}.message-meta{display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:13px;margin-bottom:7px}.message.agent{padding:16px;border:1px solid #bfdbfe;border-radius:14px;background:#eff6ff;margin-top:12px}.message-body{white-space:pre-wrap}.field{display:grid;gap:7px;margin-top:17px}.field label{font-weight:700;font-size:13px}.field input,.field textarea,.field select{width:100%;padding:10px 11px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;font:inherit}.field textarea{min-height:150px;resize:vertical}.button{display:inline-flex;align-items:center;justify-content:center;min-height:43px;padding:0 15px;border:0;border-radius:9px;background:var(--blue);color:#fff;font-weight:750;cursor:pointer}.notice{padding:11px 13px;border-radius:10px;background:#ecfdf5;color:#166534;margin-bottom:18px}.ai-box{padding:15px;border-radius:13px;background:var(--soft);margin-top:18px}.ai-box strong{display:block;margin-bottom:5px}@media(max-width:850px){.shell{padding:20px}.layout{grid-template-columns:1fr}}</style></head><body><div class="shell"><header class="top"><a href="{{ route('owner.support.index') }}">← Support inbox</a><a href="{{ route('owner.dashboard') }}">Owner console</a></header>@if(session('status'))<div class="notice">{{ session('status') }}</div>@endif<div class="layout"><main class="panel"><p class="muted">{{ $ticket->category }} · {{ $ticket->public_id }}</p><h1 class="title">{{ $ticket->subject }}</h1><p class="muted">{{ $ticket->requester_name }} · {{ $ticket->requester_email }}</p><div style="margin-top:24px">@foreach($ticket->messages as $message)<article class="message {{ $message->source === 'agent' ? 'agent' : '' }}"><div class="message-meta"><span>{{ $message->author_name }} · {{ $message->source }}</span><time>{{ optional($message->sent_at)->format('d M Y, H:i') }}</time></div><div class="message-body">{{ $message->body }}</div></article>@endforeach</div><form method="post" action="{{ route('owner.support.reply', $ticket->public_id) }}">@csrf<div class="field"><label for="message">Reply to requester</label><textarea id="message" name="message" required minlength="2" maxlength="12000"></textarea></div><button class="button" type="submit">Send reply</button></form></main><aside class="panel"><h2 style="margin-top:0">Ticket controls</h2><form method="post" action="{{ route('owner.support.update', $ticket->public_id) }}">@csrf @method('PUT')<div class="field"><label for="status">Status</label><select id="status" name="status">@foreach(['open','pending','resolved','closed'] as $status)<option value="{{ $status }}" @selected($ticket->status === $status)>{{ ucfirst($status) }}</option>@endforeach</select></div><div class="field"><label for="priority">Priority</label><select id="priority" name="priority">@foreach(['low','normal','high','urgent'] as $priority)<option value="{{ $priority }}" @selected($ticket->priority === $priority)>{{ ucfirst($priority) }}</option>@endforeach</select></div><div class="field"><button class="button" type="submit">Save controls</button></div></form><div class="ai-box"><strong>AI triage: {{ $ticket->ai_state ?? 'not analysed' }}</strong><span class="muted">@if($ticket->ai_confidence !== null)Confidence {{ number_format($ticket->ai_confidence * 100) }}%. @endifHuman review remains required for sensitive or uncertain cases.</span>@if($ticket->ai_summary)<p>{{ $ticket->ai_summary }}</p>@endif @if($ticket->ai_reply_draft)<details><summary>View draft</summary><p style="white-space:pre-wrap">{{ $ticket->ai_reply_draft }}</p></details>@endif</div></aside></div></div></body></html>
